def get_comps8(g,c):
    Hh,Ww=len(g),len(g[0]); seen=set(); out=[]
    for i in range(Hh):
        for j in range(Ww):
            if g[i][j]==c and (i,j) not in seen:
                stack=[(i,j)]; comp=set()
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.add((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<Hh and 0<=nx<Ww and g[ny][nx]==c and (ny,nx) not in seen: stack.append((ny,nx))
                out.append(sorted(comp))
    return out
