def solve(I):
    H,W=len(I),len(I[0])
    cells=defaultdict(list)
    for i in range(H):
        for j in range(W):
            if I[i][j]: cells[I[i][j]].append((i,j))
    out=[[0]*W for _ in range(H)]
    # order colors by mincol asc; within a color, stack comps sorted by input MAX-ROW DESCENDING (lowest-in-input comp on floor), one empty row above each top; horizontal: consecutive comps shifted right by prev end +1.
    s=0
    for ci in sorted(cells,key=lambda cc:min(j for i,j in cells[cc])):
        g=sorted(get_comps(I,ci),key=lambda cp:max(p[0] for p in cp),reverse=True)
        cur=H-1; c=s
        for k,cp in enumerate(g):
            h=max(p[0] for p in cp)-min(p[0] for p in cp)+1
            base=min(p[0] for p in cp); bc=min(p[1] for p in cp)
            top=cur-h+1
            for p in cp:
                y,x=top+p[0]-base,c+(p[1]-bc)
                if 0<=y<H and 0<=x<W: out[y][x]=ci
            if k<len(g)-1: cur -= h+2   # one empty ROW above this comp's top
            w=max(p[1] for p in cp)-bc+1
            s = c + w + 1              # next slot starts after 1 empty col
            c += w+1                    # next comp of same color also shifted right? probably not - same band
    return out
